/* Loop #8 C verification harness: ChaCha20-Poly1305 AEAD.
 *
 * Verifies the MoonBit implementation (src/aead/) against OpenSSH's
 * ORIGINAL C code on vectors generated by aead_python_ref.py:
 *
 *   Layer 1 (RFC 8439 core AEAD, 12-byte nonce):
 *     built here directly from chacha.c's public state struct
 *     (IETF layout: sigma|key|ctr32|nonce96) + poly1305.c.
 *     OpenSSH has no RFC 8439 helper, so this is the canonical way to
 *     exercise djb's block function in IETF form.
 *
 *   Layer 2 (OpenSSH chacha20-poly1305@openssh.com wrapper):
 *     real cipher-chachapoly.c via aead_chachapoly_ref.c.
 *
 * Expected values are COMPUTED by python cryptography - never hand-copied.
 */
#include <stdio.h>
#include "aead_ssh_compat.h"

/* OpenSSH originals: implementations pulled into this single TU */
#include "chacha.h"
#include "poly1305.h"
#include "chacha.c"    /* djb block function  ($OpenBSD) */
#include "poly1305.c"  /* donna unrolled       ($OpenBSD) */
#include "aead_chachapoly_ref.c"

static int g_fails = 0;

/* ---------------- hex helpers ---------------- */

static size_t hex_decode(const char *hex, unsigned char *out)
{
    size_t n = strlen(hex) / 2, i;
    for (i = 0; i < n; i++) {
        char c1 = hex[2 * i], c2 = hex[2 * i + 1];
        int hi = (c1 >= '0' && c1 <= '9') ? c1 - '0' :
                 (c1 >= 'a' && c1 <= 'f') ? c1 - 'a' + 10 :
                 (c1 >= 'A' && c1 <= 'F') ? c1 - 'A' + 10 : -1;
        int lo = (c2 >= '0' && c2 <= '9') ? c2 - '0' :
                 (c2 >= 'a' && c2 <= 'f') ? c2 - 'a' + 10 :
                 (c2 >= 'A' && c2 <= 'F') ? c2 - 'A' + 10 : -1;
        if (hi < 0 || lo < 0) {
            fprintf(stderr, "BAD HEX at %s\n", hex);
            exit(2);
        }
        out[i] = (unsigned char)((hi << 4) | lo);
    }
    return n;
}

static void check_bytes(const char *label, const unsigned char *got,
                        size_t gotlen, const unsigned char *want,
                        size_t wantlen)
{
    size_t i;
    if (gotlen != wantlen) {
        printf("FAIL %-40s len %lu != %lu\n", label,
               (unsigned long)gotlen, (unsigned long)wantlen);
        g_fails++;
        return;
    }
    for (i = 0; i < wantlen; i++) {
        if (got[i] != want[i]) {
            printf("FAIL %-40s byte %lu: %02x != %02x\n", label,
                   (unsigned long)i, got[i], want[i]);
            g_fails++;
            return;
        }
    }
    printf("PASS %s\n", label);
}

static void check_hex(const char *label, const unsigned char *got,
                      size_t gotlen, const char *want_hex)
{
    unsigned char want[8192];
    size_t wantlen = hex_decode(want_hex, want);
    check_bytes(label, got, gotlen, want, wantlen);
}

static void check_cond(const char *label, int ok)
{
    if (!ok) {
        printf("FAIL %s\n", label);
        g_fails++;
    } else {
        printf("PASS %s\n", label);
    }
}

/* ---------------- RFC 8439 core (IETF layout) ---------------- */

static u_int le32(const u_char *p)
{
    return ((u_int)p[0]) | ((u_int)p[1] << 8) |
           ((u_int)p[2] << 16) | ((u_int)p[3] << 24);
}

/* Build an IETF-layout state in chacha.c's public ctx.
 * Constraint: ctr32 + ceil(len/64) must not wrap 2^32. */
static void rfc8439_init(struct chacha_ctx *ctx, const u_char key[32],
                         const u_char nonce[12], uint32_t ctr)
{
    static const u_char sigma[16] = "expand 32-byte k";
    int i;
    memset(ctx, 0, sizeof(*ctx));
    ctx->input[0] = le32(sigma);
    ctx->input[1] = le32(sigma + 4);
    ctx->input[2] = le32(sigma + 8);
    ctx->input[3] = le32(sigma + 12);
    for (i = 0; i < 8; i++)
        ctx->input[4 + i] = le32(key + 4 * i);
    ctx->input[12] = (u_int)ctr;      /* 32-bit counter   */
    ctx->input[13] = le32(nonce + 0); /* 96-bit nonce     */
    ctx->input[14] = le32(nonce + 4);
    ctx->input[15] = le32(nonce + 8);
}

static void rfc8439_crypt(struct chacha_ctx *ctx, const u_char *in,
                          u_char *out, size_t len)
{
    size_t pos = 0;
    while (pos < len) {
        u_int take = (len - pos > 64) ? 64 : (u_int)(len - pos);
        chacha_encrypt_bytes(ctx, in + pos, out + pos, take);
        pos += take;
    }
}

static void put_u64le(u_char *p, uint64_t v)
{
    int i;
    for (i = 0; i < 8; i++)
        p[i] = (unsigned char)(v >> (8 * i));
}

/* aad ‖ pad16(aad) ‖ ct ‖ pad16(ct) ‖ LE64(|aad|) ‖ LE64(|ct|) */
static size_t build_mac_data(const u_char *aad, size_t aadlen,
                             const u_char *ct, size_t ctlen,
                             u_char *buf, size_t bufsz)
{
    size_t off = 0;
    size_t pad_aad = (16 - aadlen % 16) % 16;
    size_t pad_ct = (16 - ctlen % 16) % 16;
    if (bufsz < aadlen + pad_aad + ctlen + pad_ct + 16)
        exit(2); /* harness bug guard */
    if (aadlen) memcpy(buf + off, aad, aadlen);
    off += aadlen;
    memset(buf + off, 0, pad_aad);
    off += pad_aad;
    memcpy(buf + off, ct, ctlen);
    off += ctlen;
    memset(buf + off, 0, pad_ct);
    off += pad_ct;
    put_u64le(buf + off, (uint64_t)aadlen);
    put_u64le(buf + off + 8, (uint64_t)ctlen);
    off += 16;
    return off;
}

static void rfc8439_poly_key(const u_char key[32], const u_char nonce[12],
                             u_char pk[POLY1305_KEYLEN])
{
    u_char zeros[POLY1305_KEYLEN] = {0};
    struct chacha_ctx ctx;
    rfc8439_init(&ctx, key, nonce, 0); /* block counter 0 */
    chacha_encrypt_bytes(&ctx, zeros, pk, sizeof(zeros));
}

static void rfc8439_encrypt(const u_char key[32], const u_char nonce[12],
                            const u_char *aad, size_t aadlen,
                            const u_char *pt, size_t ptlen,
                            u_char *ct_tag /* ptlen+16 */)
{
    u_char pk[POLY1305_KEYLEN];
    u_char mac_data[8192];
    struct chacha_ctx ctx;
    rfc8439_poly_key(key, nonce, pk);
    rfc8439_init(&ctx, key, nonce, 1); /* payload starts at counter 1 */
    if (ptlen) rfc8439_crypt(&ctx, pt, ct_tag, ptlen);
    {
        size_t mdlen = build_mac_data(aad, aadlen, ct_tag, ptlen,
                                      mac_data, sizeof(mac_data));
        poly1305_auth(ct_tag + ptlen, mac_data, mdlen, pk);
    }
    explicit_bzero(pk, sizeof(pk));
    explicit_bzero(mac_data, sizeof(mac_data));
}

/* returns 1 if tag valid and plaintext recovered (see _full below) */
static int rfc8439_decrypt_full(const u_char key[32], const u_char nonce[12],
                                const u_char *aad, size_t aadlen,
                                const u_char *ct_tag, size_t total,
                                u_char *pt, size_t ptsz);

/* ---------------- test sections ---------------- */

#define KAT_KEY  "808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9f"
#define KAT_NONCE "070000004041424344454647"
#define KAT_AAD  "50515253c0c1c2c3c4c5c6c7"
/* "Ladies and Gentlemen of the class of '99: ..." */
#define KAT_PT \
    "4c616469657320616e642047656e746c656d656e206f662074686520636c61" \
    "7373206f66202739393a204966204920636f756c64206f6666657220796f75" \
    "206f6e6c79206f6e652074697020666f7220746865206675747572652c2073" \
    "756e73637265656e20776f756c642062652069742e"
#define KAT_CT \
    "d31a8d34648e60db7b86afbc53ef7ec2a4aded51296e08fea9e2b5a736ee62d6" \
    "3dbea45e8ca9671282fafb69da92728b1a71de0a9e060b2905d6a5b67ecd3b36" \
    "92ddbd7f2d778b8c9803aee328091b58fab324e4fad675945585808b4831d7bc" \
    "3ff4def08e4b7a9de576d26586cec64b6116"
#define KAT_TAG "1ae10b594f09e26a7e902ecbd0600691"
#define A2_TAG  "6a23a4681fd59456aea1d29f82477216" /* empty aad       */
#define A3_TAG  "e622e5647a38d967a7ecbcb46c7f675c" /* empty plaintext */
#define A4_TAG  "a0784d7a4716f3feb4f64e7f4b39bf04" /* both empty      */

static void run_rfc8439_kat(void)
{
    unsigned char key[32], nonce[12], aad[12];
    unsigned char pt[512], ct_tag[1024], back[512];

    hex_decode(KAT_KEY, key);
    hex_decode(KAT_NONCE, nonce);
    hex_decode(KAT_AAD, aad);

    { /* A1: full official vector */
        size_t ptlen = hex_decode(KAT_PT, pt);
        rfc8439_encrypt(key, nonce, aad, 12, pt, ptlen, ct_tag);
        check_hex("C/A1 rfc8439 ct  ", ct_tag, ptlen, KAT_CT);
        check_hex("C/A1 rfc8439 tag ", ct_tag + ptlen, 16, KAT_TAG);

        /* decrypt roundtrip */
        memset(back, 0, sizeof(back));
        if (rfc8439_decrypt_full(key, nonce, aad, 12, ct_tag, ptlen + 16,
                                 back, sizeof(back)))
            check_bytes("C/A1 rfc8439 decrypt", back, ptlen, pt, ptlen);
        else
            check_cond("C/A1 rfc8439 decrypt", 0);

        /* tamper ciphertext -> reject */
        ct_tag[10] ^= 0x01;
        check_cond("C/A1 tamper ct rejected",
                   !rfc8439_decrypt_full(key, nonce, aad, 12, ct_tag,
                                         ptlen + 16, back, sizeof(back)));
        ct_tag[10] ^= 0x01;
        /* tamper tag -> reject */
        ct_tag[ptlen] ^= 0x80;
        check_cond("C/A1 tamper tag rejected",
                   !rfc8439_decrypt_full(key, nonce, aad, 12, ct_tag,
                                         ptlen + 16, back, sizeof(back)));
    }
    { /* A2: empty aad */
        size_t ptlen = hex_decode(KAT_PT, pt);
        rfc8439_encrypt(key, nonce, aad, 0, pt, ptlen, ct_tag);
        check_hex("C/A2 empty-aad tag ", ct_tag + ptlen, 16, A2_TAG);
    }
    { /* A3: empty plaintext */
        rfc8439_encrypt(key, nonce, aad, 12, NULL, 0, ct_tag);
        check_hex("C/A3 empty-pt tag  ", ct_tag, 16, A3_TAG);
    }
    { /* A4: both empty */
        rfc8439_encrypt(key, nonce, NULL, 0, NULL, 0, ct_tag);
        check_hex("C/A4 empty-both tag", ct_tag, 16, A4_TAG);
    }
}

/* RFC 8439 AEAD decrypt: verify tag first, then recover plaintext.
 * Returns 1 on success, 0 on MAC mismatch. */
static int rfc8439_decrypt_full(const u_char key[32], const u_char nonce[12],
                                const u_char *aad, size_t aadlen,
                                const u_char *ct_tag, size_t total,
                                u_char *pt, size_t ptsz)
{
    u_char pk[POLY1305_KEYLEN], expect[POLY1305_TAGLEN];
    static u_char mac_data[16384];
    size_t ctlen = total - 16, mdlen;
    struct chacha_ctx ctx;

    if (ptsz < total - 16)
        exit(2);
    rfc8439_poly_key(key, nonce, pk);
    mdlen = build_mac_data(aad, aadlen, ct_tag, ctlen,
                           mac_data, sizeof(mac_data));
    poly1305_auth(expect, mac_data, mdlen, pk);
    explicit_bzero(pk, sizeof(pk));
    explicit_bzero(mac_data, sizeof(mac_data));
    if (timingsafe_bcmp(expect, ct_tag + ctlen, POLY1305_TAGLEN) != 0)
        return 0;
    rfc8439_init(&ctx, key, nonce, 1);
    if (ctlen)
        rfc8439_crypt(&ctx, ct_tag, pt, ctlen);
    return 1;
}

/* ---------------- Section B: OpenSSH wire wrapper ---------------- */

#define W_KEY64 \
    "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f" \
    "202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f"
#define B1_HDR    "deadbeef"
#define B1_PAY    "68656c6c6f20636861636861706f6c79207772617070657221"
#define B1_WRAPPED \
    "4ae8b0b670dd2e5dc2c6c5b972023400df2c225ed8c6819491dd3e2ecd727cee" \
    "6cc575bba0aba1ca13106344fb"
#define B2_HDR    "00000100"
#define B2_PAY \
    "0b121920272e353c434a51585f666d747b828990979ea5acb3bac1c8cfd6dde4" \
    "ebf2f900070e151c232a31383f464d545b626970777e858c939aa1a8afb6bdc4" \
    "cbd2d9e0e7eef5fc030a11181f262d343b424950575e656c737a81888f969da4" \
    "abb2b9c0"
#define B2_WRAPPED \
    "9e19c7b7d7d64788fb0b3e8ff985a9c2b59b0d7931f8e61f1580d338c6c434c7" \
    "5bf209343aca37efb8587586b8f9ec1a7aa47a304df615f5524ec6685e52c9e7" \
    "c9bc79989b507c4b213e732d0c1f442dcf730e7b66254ed2be41cef5aa88e17b" \
    "fa91d3b9258aa023d50233bb0081866dbdaf23e9e205b64f"
#define B3_SEQNR  0xFFFFFFFFu
#define B3_HDR    "0000001c"
#define B3_PAY    "41414141"
#define B3_WRAPPED "b90ee4ac48d34ddabce51c3dc6fda3809a06b901a68d7a2c"

static void run_wrapper_case(const char *name, u_int seqnr,
                             const char *hdr_hex, const char *pay_hex,
                             const char *wrapped_hex)
{
    unsigned char key64[64], hdr[64], pay[4096];
    unsigned char dest[8192], plain[8192], expect[8192];
    size_t aadlen, datalen;
    struct chachapoly_ctx *ctx;
    u_int got_len;
    char label[160];

    hex_decode(W_KEY64, key64);
    aadlen = hex_decode(hdr_hex, hdr);
    datalen = hex_decode(pay_hex, pay);

    ctx = chachapoly_new(key64, 64);
    if (ctx == NULL) {
        check_cond(name, 0);
        return;
    }

    /* encrypt: src = hdr||pay (no tag yet), dest gets hdr_ct||pay_ct||tag */
    memcpy(expect, hdr, aadlen);
    memcpy(expect + aadlen, pay, datalen);
    if (chachapoly_crypt(ctx, seqnr, dest, expect, (u_int)datalen,
                         (u_int)aadlen, 16, 1) != 0) {
        snprintf(label, sizeof(label), "%s encrypt rv", name);
        check_cond(label, 0);
    } else {
        snprintf(label, sizeof(label), "%s encrypt", name);
        check_hex(label, dest, aadlen + datalen + 16, wrapped_hex);
    }

    /* get_length on encrypted header */
    if (chachapoly_get_length(ctx, &got_len, seqnr, dest, (u_int)aadlen) != 0) {
        snprintf(label, sizeof(label), "%s get_length rv", name);
        check_cond(label, 0);
    } else {
        snprintf(label, sizeof(label), "%s get_length (%08x)", name, got_len);
        check_cond(label, got_len == PEEK_U32(hdr));
    }

    /* decrypt: verify tag + recover hdr||pay */
    if (chachapoly_crypt(ctx, seqnr, plain, dest, (u_int)datalen,
                         (u_int)aadlen, 16, 0) != 0) {
        snprintf(label, sizeof(label), "%s decrypt rv", name);
        check_cond(label, 0);
    } else {
        snprintf(label, sizeof(label), "%s decrypt", name);
        check_bytes(label, plain, aadlen + datalen, expect, aadlen + datalen);
    }

    /* negative: tampered body must fail with SSH_ERR_MAC_INVALID */
    {
        unsigned char bad[8192];
        memcpy(bad, dest, aadlen + datalen + 16);
        bad[aadlen] ^= 0x40; /* first payload byte */
        {
            int rv = chachapoly_crypt(ctx, seqnr, plain, bad, (u_int)datalen,
                                      (u_int)aadlen, 16, 0);
            snprintf(label, sizeof(label), "%s tamper->MAC_INVALID", name);
            check_cond(label, rv == SSH_ERR_MAC_INVALID);
        }
        memcpy(bad, dest, aadlen + datalen + 16);
        bad[aadlen + datalen + 15] ^= 0x01; /* last tag byte */
        {
            int rv = chachapoly_crypt(ctx, seqnr, plain, bad, (u_int)datalen,
                                      (u_int)aadlen, 16, 0);
            snprintf(label, sizeof(label), "%s tamper-tag->MAC_INVALID", name);
            check_cond(label, rv == SSH_ERR_MAC_INVALID);
        }
        /* wrong seqnr -> different poly_key -> MAC_INVALID */
        {
            int rv = chachapoly_crypt(ctx, seqnr ^ 1u, plain, dest,
                                      (u_int)datalen, (u_int)aadlen, 16, 0);
            snprintf(label, sizeof(label), "%s wrong-seq->MAC_INVALID", name);
            check_cond(label, rv == SSH_ERR_MAC_INVALID);
        }
    }
    chachapoly_free(ctx);
}

int main(void)
{
    printf("=== Loop #8 AEAD harness: OpenSSH original C vs python/MoonBit ===\n");

    printf("--- Section A: RFC 8439 core (built from chacha.c IETF state) ---\n");
    run_rfc8439_kat();

    printf("--- Section B: OpenSSH cipher-chachapoly.c wrapper ---\n");
    run_wrapper_case("C/B1 wrap seq=0          ", 0u,
                     B1_HDR, B1_PAY, B1_WRAPPED);
    run_wrapper_case("C/B2 wrap seq=11223344   ", 0x11223344u,
                     B2_HDR, B2_PAY, B2_WRAPPED);
    run_wrapper_case("C/B3 wrap seq=ffffffff   ", B3_SEQNR,
                     B3_HDR, B3_PAY, B3_WRAPPED);

    printf("=== %s (fails=%d) ===\n",
           g_fails == 0 ? "ALL PASS" : "FAILED", g_fails);
    return g_fails == 0 ? 0 : 1;
}
